typedef enum { SHAPE_CIRCLE, SHAPE_RECT } shape_kind;
typedef struct {
    shape_kind kind;
    union { struct { double r; } circle; struct { double w, h; } rect; } u;
} shape;

double area(const shape *s) {
    switch (s->kind) {                 /* -Wswitch-enum: missing tag => warning */
    case SHAPE_CIRCLE: return 3.14159265358979 * s->u.circle.r * s->u.circle.r;
    case SHAPE_RECT:   return s->u.rect.w * s->u.rect.h;
    default:           abort();        /* unreachable once coverage is complete */
    }
}
